file.content:
$venvs = @(
    # morning-briefing venv dropped 2026-08-14 with the job above. Later that day the
    # retirement was completed: project removed from disk, secrets destroyed, and the
    # backup-manifest.json entry deleted. Code lives at github.com/erash11/morning-briefing;
    # its 56 briefings remain at ~/SecondBrain/morning-briefings/ and are now in the
    # memsearch index set. See KeystoneOS/projects/retired/morning_briefing.md.
    # A Windows venv keeps its interpreter in Scripts\, not bin/.
    $(if ($onWindows) { "$HOME/.claude/claude-memory-compiler/.venv/Scripts/python.exe" }
      else { "$HOME/.claude/claude-memory-compiler/.venv/bin/python" })
)
foreach ($py in $venvs) {
    if (-not (Test-Path $py)) { "$py : MISSING"; $fail += "venv-missing"; continue }
    $v = & $py -c "import sys; print(sys.version.split()[0])" 2>&1
    if ($LASTEXITCODE -eq 0) { "$py : OK ($v)" } else { "$py : BROKEN -> $v"; $fail += "venv-broken" }
}

Section "memsearch"
$ms = Get-Command memsearch -ErrorAction SilentlyContinue
if (-not $ms) { "memsearch: NOT ON PATH"; $fail += "memsearch-path" }
else {
    "exe: $($ms.Source)"
    $out = & memsearch search "healthcheck" --top-k 1 2>&1 | Select-Object -First 3
    if ($LASTEXITCODE -eq 0) { "search: OK" } else { "search: FAIL -> $out"; $fail += "memsearch-run" }
}
if ($onWindows) {
    # On the laptop memsearch talks to Milvus in Docker Desktop (WSL2). With Docker down,
    # every memsearch hook times out and the search above fails with an unhelpful error,
    # so name the real cause.
    $st = & docker ps --filter "name=milvus-standalone" --format "{{.Status}}" 2>&1
    if ($LASTEXITCODE -ne 0) { "milvus: Docker not reachable - start Docker Desktop"; $fail += "milvus-docker" }
    elseif ("$st" -match '\(healthy\)') { "milvus: $st" }
    else { "milvus: NOT HEALTHY ('$st')"; $fail += "milvus-down" }
}

Section "Memory pipeline"
$errlog = "$HOME/.claude/global-memory/transcripts/.errors.log"
if ((Test-Path $errlog) -and ((Get-Item -Force $errlog).Length -gt 0)) {
    "errors.log: NON-EMPTY (hook failures below)"; Get-Content $errlog -Tail 5; $fail += "errors-log"
} else { "errors.log: clean" }

input.new_string:
    else { "milvus: NOT HEALTHY ('$st')"; $fail += "milvus-down" }
}

Section "Recall coverage"
# Every configured index root must exist on this machine, or it is silently never indexed.
# The {VAULT} bug (2026-09-30) hid ~1,370 vault notes from Windows search for weeks this way.
# The other machine's Tier A slug is the one expected absence.
$devRoot = @("$HOME/DEV", "$HOME/Desktop/DEV") | Where-Object { Test-Path "$_/KeystoneOS" } | Select-Object -First 1
$vaultRoot = @("$HOME/SecondBrain", "$HOME/Desktop/SecondBrain") | Where-Object { Test-Path $_ } | Select-Object -First 1
$idxCfg = "$devRoot/KeystoneOS/data/memory-index-paths.json"
if (-not (Test-Path $idxCfg)) { "index config: MISSING ($idxCfg)"; $fail += "recall-coverage" }
else {
    $otherSlug = if ($onWindows) { '-Users-kristinarash-' } else { 'C--Users-eric-rash' }
    $idxPaths = @((Get-Content -Raw $idxCfg | ConvertFrom-Json).paths | ForEach-Object {
        (($_ -replace '\{HOME\}', $HOME) -replace '\{DEV\}', $devRoot) -replace '\{VAULT\}', $vaultRoot })
    $gone = @($idxPaths | Where-Object { -not (Test-Path -LiteralPath $_) -and $_ -notmatch [regex]::Escape($otherSlug) })
    if ($gone.Count) { "roots: $($gone.Count) MISSING -> $($gone -join '; ')"; $fail += "recall-coverage" }
    else { "roots: all $($idxPaths.Count) resolve (other machine's slug excepted)" }
}
# Recall eval ledger (audits/recall-eval): flag a drop of 2+ hit@5 between this machine's
# last two runs of the same backend. The eval itself is run by hand or after a reindex.
$ledger = "$HOME/.claude/audits/recall-eval/ledger.md"
if (Test-Path $ledger) {
    $me = [System.Net.Dns]::GetHostName().ToLower()
    $rows = @(Get-Content $ledger | Where-Object { $_ -match '^\| \d{4}-' } | ForEach-Object {
        $c = $_.Trim('|').Split('|') | ForEach-Object { $_.Trim() }
        [pscustomobject]@{ Date = $c[0]; Machine = $c[1]; Backend = $c[3]; Hit5 = [int]$c[6] } } | Where-Object { $_.Machine -eq $me })
    foreach ($g in ($rows | Group-Object Backend)) {
        $last = $g.Group | Select-Object -Last 2
        $latest = $last[-1]
        if ($last.Count -eq 2 -and ($last[0].Hit5 - $latest.Hit5) -ge 2) {
            "eval $($g.Name): hit@5 fell $($last[0].Hit5) -> $($latest.Hit5) ($($latest.Date))"; $fail += "recall-regress"
        } else { "eval $($g.Name): hit@5 $($latest.Hit5) ($($latest.Date))" }
    }
} else { "eval: no ledger yet (python ~/.claude/audits/recall-eval/recall-eval.py)" }

toolu_01TXJqpwwqUoSTXhkSFjGk5x.new_string:
    else { "milvus: NOT HEALTHY ('$st')"; $fail += "milvus-down" }
}

