    if (-not $vaultRoot) { $vaultRoot = Join-Path $homeDir 'SecondBrain' }
    return @($json.paths |
        ForEach-Object { ((($_ -replace '\{HOME\}', $homeDir) -replace '\{DEV\}', $devRoot) -replace '\{VAULT\}', $vaultRoot) -replace '/', '\' } |
        Where-Object { Test-Path -LiteralPath $_ })
}

try {
    $keystoneRoot = Resolve-KeystoneRoot -Root $Root -ScriptPath $MyInvocation.MyCommand.Path
    $transcriptsDir = Join-Path $env:USERPROFILE ".claude\global-memory\transcripts"
    $errLog = Join-Path $transcriptsDir ".errors.log"
    $indexLog = Join-Path $transcriptsDir ".memsearch-index.log"
    $lockFile = Join-Path $transcriptsDir ".memsearch-index.lock"
    # The indexer can legitimately exceed 30 seconds while loading the ONNX
    # model. Reclaim only a lock whose recorded owner is gone; age is a fallback
    # for locks written by older versions without an owner PID.
    $lockStaleMs = 5 * 60 * 1000

    function Test-LockOwnerAlive {
        param([string]$Path)
        try {
            $ownerPid = [int](Get-Content -Raw -LiteralPath $Path)
            if ($ownerPid -le 0) { return $false }
            $null = Get-Process -Id $ownerPid -ErrorAction Stop
            return $true
        }
        catch { return $false }
    }

    $paths = Resolve-IndexPaths -KeystoneRoot $keystoneRoot
    if ($paths.Count -eq 0) { exit 0 }

    $memsearch = Get-Command memsearch -ErrorAction SilentlyContinue
    if (-not $memsearch) { exit 0 }

    # Codex fires Stop after EVERY turn, so without this a busy session started a
    # 45s index each turn. Share the Claude hook's cooldown file (memsearch-sync.js,
    # 30 min, mtime-based) so the two harnesses start at most one index per window.
    $lastRunFile = Join-Path $transcriptsDir ".memsearch-last-run"
    $cooldownMin = 30
    if ((Test-Path -LiteralPath $lastRunFile) -and
        ((Get-Date) - (Get-Item -LiteralPath $lastRunFile).LastWriteTime).TotalMinutes -lt $cooldownMin) { exit 0 }

    $haveLock = $false
    try {
        $fs = [System.IO.File]::Open($lockFile, [System.IO.FileMode]::CreateNew)
        $fs.Close()
        [System.IO.File]::WriteAllText($lockFile, [string]$PID)
        $haveLock = $true
    }
    catch {
        if (Test-LockOwnerAlive -Path $lockFile) { exit 0 }
        $stale = $true
        try {
            $ageMs = ((Get-Date) - (Get-Item -LiteralPath $lockFile).LastWriteTime).TotalMilliseconds
            $stale = $ageMs -ge $lockStaleMs
        }
        catch { $stale = $true }
        if (-not $stale) { exit 0 }
        try {
            Remove-Item -LiteralPath $lockFile -Force -ErrorAction Stop
            $fs = [System.IO.File]::Open($lockFile, [System.IO.FileMode]::CreateNew)
            $fs.Close()
            [System.IO.File]::WriteAllText($lockFile, [string]$PID)
            $haveLock = $true
        }
        catch { exit 0 }
    }

    try {
        $env:PYTHONIOENCODING = "utf-8"
        $env:PYTHONUTF8 = "1"

        $stdoutFile = [System.IO.Path]::GetTempFileName()
        $stderrFile = [System.IO.Path]::GetTempFileName()
        $proc = Start-Process -FilePath $memsearch.Source `
            -ArgumentList (@("index") + $paths) `
            -NoNewWindow -PassThru `
            -RedirectStandardOutput $stdoutFile -RedirectStandardError $stderrFile
        # Under Windows PowerShell 5.1, ExitCode is $null unless the process
        # handle is referenced before exit — and $null -ne 0 routed every run,
        # including successes, into the .errors.log branch.
        $null = $proc.Handle

        $finished = $proc.WaitForExit(45000)
        $out = (Get-Content -Raw -LiteralPath $stdoutFile -ErrorAction SilentlyContinue) + `
               (Get-Content -Raw -LiteralPath $stderrFile -ErrorAction SilentlyContinue)
        Remove-Item -LiteralPath $stdoutFile, $stderrFile -ErrorAction SilentlyContinue

        if (-not $finished) {
            # memsearch launches a Python child; kill the full tree so a timed
            # out hook cannot leave a high-RAM orphan indexing in the background.
            try { & taskkill.exe /T /F /PID $proc.Id 2>&1 | Out-Null } catch {}
            Add-Content -LiteralPath $indexLog -Value "[$( (Get-Date).ToString('o') )] codex memsearch-sync: timed out at 45s (non-fatal, next run catches up)"
        }
        elseif ($proc.ExitCode -ne 0 -and $out -match 'Fail connecting to server') {
            # Milvus not up yet (Docker starts after login; morning scheduled
            # sessions can end first). Transient and self-healing — the next
            # incremental index catches up. Note it, don't escalate.
            Add-Content -LiteralPath $indexLog -Value "[$( (Get-Date).ToString('o') )] codex memsearch-sync: Milvus unreachable (transient, next run catches up)"
        }
        elseif ($proc.ExitCode -ne 0) {
            Add-Content -LiteralPath $errLog -Value "[$( (Get-Date).ToString('o') )] codex memsearch-sync: index exit $($proc.ExitCode): $($out.Substring(0, [Math]::Min(300, $out.Length)))"
        }
        else {
            Set-Content -LiteralPath $indexLog -Value ($out.Trim() + "`n") -Encoding UTF8
        }
    }
    finally {
        if ($haveLock) { try { Remove-Item -LiteralPath $lockFile -ErrorAction SilentlyContinue } catch {} }
    }
}
catch {
    # Never fail the Codex Stop event over indexing problems.
}

exit 0

